import{_ as e,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Create Cart","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-cart-token","title":"Create Cart","description":"Start a cart and receive the cart token that identifies it on every later call.","request":"curl -X POST \\"http://localhost/api/shop/cart-tokens\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -d \'{}\'\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 492,\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"customerId\\": null,\\n  \\"channelId\\": 1,\\n  \\"itemsCount\\": 0,\\n  \\"itemsQty\\": null,\\n  \\"items\\": [],\\n  \\"subtotal\\": 0,\\n  \\"baseSubtotal\\": 0,\\n  \\"discountAmount\\": 0,\\n  \\"baseDiscountAmount\\": 0,\\n  \\"taxAmount\\": 0,\\n  \\"baseTaxAmount\\": 0,\\n  \\"shippingAmount\\": 0,\\n  \\"baseShippingAmount\\": 0,\\n  \\"grandTotal\\": 0,\\n  \\"baseGrandTotal\\": 0,\\n  \\"formattedSubtotal\\": \\"$0.00\\",\\n  \\"formattedDiscountAmount\\": \\"$0.00\\",\\n  \\"formattedTaxAmount\\": \\"$0.00\\",\\n  \\"formattedShippingAmount\\": \\"$0.00\\",\\n  \\"formattedGrandTotal\\": \\"$0.00\\",\\n  \\"couponCode\\": null,\\n  \\"isGuest\\": true\\n}\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/create-cart.md","filePath":"api/rest-api/shop/cart/create-cart.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/shop/cart/create-cart.md"};function n(s,t,c,i,l,h){return o(),a("div",null,t[0]||(t[0]=[d('<h1 id="create-cart" tabindex="-1">Create Cart <a class="header-anchor" href="#create-cart" aria-label="Permalink to &quot;Create Cart&quot;">​</a></h1><p>Start a shopping cart and obtain the <strong>cart token</strong> that identifies it. A guest client calls this once at the beginning of a session and reuses the returned token for every subsequent cart and checkout call.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/cart-tokens</span></span></code></pre></div><p>The path is <code>/cart-tokens</code>, not <code>/cart</code> — <code>/api/shop/cart</code> is the read endpoint documented on <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a>.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>No</td><td>A signed-in customer&#39;s Bearer token, to tie the cart to their account</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>Send an empty object. The endpoint takes no fields — items are added afterwards with <a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>The response is the newly created cart, returned as a bare object with no wrapper.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Cart ID.</td></tr><tr><td><code>cartToken</code></td><td>string</td><td><strong>Send this as <code>Authorization: Bearer &lt;cartToken&gt;</code> on every later cart call.</strong></td></tr><tr><td><code>customerId</code></td><td>integer</td><td>Owning customer, or <code>null</code> for a guest cart.</td></tr><tr><td><code>channelId</code></td><td>integer</td><td>Channel the cart belongs to.</td></tr><tr><td><code>itemsCount</code></td><td>integer</td><td>Number of line items. <code>0</code> on a new cart.</td></tr><tr><td><code>itemsQty</code></td><td>integer</td><td>Total units across those lines.</td></tr><tr><td><code>items</code></td><td>array</td><td>Line items — empty on a new cart.</td></tr><tr><td><code>subtotal</code> / <code>baseSubtotal</code></td><td>decimal</td><td>Items subtotal, in cart and base currency.</td></tr><tr><td><code>discountAmount</code> / <code>baseDiscountAmount</code></td><td>decimal</td><td>Discount applied.</td></tr><tr><td><code>taxAmount</code> / <code>baseTaxAmount</code></td><td>decimal</td><td>Tax calculated.</td></tr><tr><td><code>shippingAmount</code> / <code>baseShippingAmount</code></td><td>decimal</td><td>Shipping cost.</td></tr><tr><td><code>grandTotal</code> / <code>baseGrandTotal</code></td><td>decimal</td><td>Grand total.</td></tr><tr><td><code>formattedSubtotal</code>, <code>formattedDiscountAmount</code>, <code>formattedTaxAmount</code>, <code>formattedShippingAmount</code>, <code>formattedGrandTotal</code></td><td>string</td><td>The same amounts, currency-formatted for display.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td>Applied coupon, or <code>null</code>.</td></tr><tr><td><code>isGuest</code></td><td>boolean</td><td>Whether the cart belongs to a guest.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Start a guest session</strong> — call once, store <code>cartToken</code>, and send it on every cart and checkout request.</li><li><strong>Start a signed-in session</strong> — send the customer&#39;s Bearer token as well, so the cart is tied to their account and survives across devices.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Store the <code>cartToken</code>, not the cart <code>id</code></strong> — the token is what authenticates later calls; the numeric ID is informational</li><li><strong>Create the cart once per session</strong> — calling again issues a new empty cart and orphans the previous one</li><li><strong>Merge after login</strong> — a guest who signs in mid-session should call <a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a> so their items survive</li><li><strong>Expect an empty cart, not an error</strong> — a newly created cart has <code>itemsCount: 0</code> and zeroed totals</li></ol><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li><li><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> — add a product of any type to the cart</li><li><a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a> — fold a guest cart into the customer&#39;s cart after login</li></ul>',19)]))}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
